    _unit(n: 3, title: 'الرقم 2', age: '3–4 سنوات', description: 'التعرف على 2 والعد إلى اثنين.', learnTitle: 'نتعرف على 2', explanation: 'الرقم 2 يمثل شيئين.', examples: ['2 كرتان', '2 نجمتان'], extra: [const TraceActivityConfig(2), const DragCountActivityConfig(2)], quiz: [_q('كم نجمة تمثل 2؟', ['1', '2', '3'], 1), _q('ما الرقم بعد 1؟', ['0', '2', '3'], 1)]),
    _unit(n: 4, title: 'الرقم 3', age: '3–4 سنوات', description: 'التعرف على 3 والعد والمطابقة.', learnTitle: 'نتعرف على 3', explanation: 'نعد 1 ثم 2 ثم 3، والعدد الأخير يمثل الكمية.', examples: ['3 كرات', '3 كتب'], extra: [const TraceActivityConfig(3), const DragCountActivityConfig(3)], quiz: [_q('ما الرقم بعد 2؟', ['1', '3', '4'], 1), _q('كم كرة تمثل 3؟', ['2', '3', '4'], 1)]),
